python - <<'PY'
p = "src/app/store-productivity/assets/_assets/component/useAssetDeletion.ts"
s = open(p, encoding="utf-8").read()

old = '''  /** Expand the selection into the rows the delete will actually close, and
   *  snapshot them. Called before the request, never after.'''
new = '''  /**
   * Attach each split fixture's slot config to the snapshot.
   *
   * Without this, undoing the deletion of a fixture that was split TODAY
   * restores its slot rows but not the AM.AssetSlotConfig that defines them
   * — BulkDeleteAsset hard-deletes a same-day config, so there is nothing
   * left for the restore proc to reopen. The result isn't a fixture without
   * its split: it is slot rows with no config to derive them from, and the
   * viewer's synthesis loop skips a parent in exactly that state, so the
   * fixture disappears from the plan while its rows sit in this grid.
   *
   * Only runs when the snapshot actually contains slot rows — a config only
   * exists for a fixture that has them, so there is nothing to fetch
   * otherwise, and an ordinary delete pays nothing.
   *
   * A failed fetch is NOT fatal. The delete is what the user asked for and
   * must not be blocked by the undo's homework; the snapshot degrades to
   * one without configs, which is the behaviour this replaces.
   */
  const withSlotConfigs = async (
    snapshot: readonly DeletableAssetRow[],
  ): Promise<readonly DeletableAssetRow[]> => {
    if (!snapshot.some((row) => row.isSlot)) return snapshot;
    try {
      const response = await fetch(
        `/api/store-productivity/get-asset-slot-configs?costCentre=${encodeURIComponent(costCentre)}`,
      );
      const json = await response.json();
      if (!response.ok || !json?.success || !json.data) return snapshot;
      const configs = json.data as Record<string, SlotConfigLike>;
      return snapshot.map((row) =>
        configs[row.id] ? { ...row, slotConfig: configs[row.id] } : row,
      );
    } catch (error) {
      console.error("[useAssetDeletion] slot config snapshot failed:", error);
      return snapshot;
    }
  };

  /** Expand the selection into the rows the delete will actually close, and
   *  snapshot them. Called before the request, never after.'''
assert s.count(old) == 1
s = s.replace(old, new)

s = s.replace('''  type DeletableAssetRow,
} from "@/lib/assets/deleteTargets";''', '''  type DeletableAssetRow,
  type SlotConfigLike,
} from "@/lib/assets/deleteTargets";''')

# Single delete
old_single = '''    enqueueMutation(async () => {
      try {
        const result = await deleteRequest(targets.ids);
        if (result.success) {
          recordDelete(targets.snapshot);
          setIsDeleting(false);'''
new_single = '''    enqueueMutation(async () => {
      try {
        // Configs first: the rows are still open at this point, and closed
        // by the time the next statement returns.
        const snapshot = await withSlotConfigs(targets.snapshot);
        const result = await deleteRequest(targets.ids);
        if (result.success) {
          recordDelete(snapshot);
          setIsDeleting(false);'''
assert s.count(old_single) == 1
s = s.replace(old_single, new_single)

# Bulk delete
old_bulk = '''    enqueueMutation(async () => {
      try {
        const result = await deleteRequest(targets.ids);
        setIsBulkDeleting(false);

        if (result.success) {
          recordDelete(targets.snapshot);'''
new_bulk = '''    enqueueMutation(async () => {
      try {
        const snapshot = await withSlotConfigs(targets.snapshot);
        const result = await deleteRequest(targets.ids);
        setIsBulkDeleting(false);

        if (result.success) {
          recordDelete(snapshot);'''
assert s.count(old_bulk) == 1
s = s.replace(old_bulk, new_bulk)

open(p, "w", encoding="utf-8", newline="").write(s)
print("ok")
